import { Component, OnInit } from '@angular/core';
import {
  ModalController, NavParams, AlertController,
  Platform,
} from '@ionic/angular';


@Component({
  selector: 'app-pp-mark-attendance',
  templateUrl: './pp-mark-attendance.page.html',
  styleUrls: ['./pp-mark-attendance.page.scss'],
})
export class PpMarkAttendancePage implements OnInit {

  paramData: any = {};
  private alert: HTMLIonAlertElement;

  constructor(private modalCtrl: ModalController, private navParams: NavParams, private alertController: AlertController) {
    this.paramData = this.navParams.get('data');
    debugger
  }

  ngOnInit() {
  }

  closeModal() {
    this.modalCtrl.dismiss({
      callBackVal: 4
    });
  }

  async callParentFun(val) { 
    debugger
    if (val == 3) {
      let msg = '';
      let isNotverify: boolean = false;
      if (this.paramData.isPhotoVerified!=1) {
        isNotverify = true;
        msg = "Selfie photo not verified , Please take Selfie photo!/செல்ஃபி புகைப்படம் சரிபார்க்கப்படவில்லை, செல்ஃபி புகைப்படம் எடுங்கள்!"
      } else {
        this.modalCtrl.dismiss({
          callBackVal: val
        });
      }
      if (isNotverify) {
        this.alert = await this.alertController.create({
          header: 'Confirmation',
          message: msg,
          buttons: [
            {
              text: 'Okay',
              cssClass: 'custom-button',
              handler: () => {
                this.modalCtrl.dismiss({
                  callBackVal: 2
                });
              }
            }
          ]
        });
        await this.alert.present();
      }
    } else {
      this.modalCtrl.dismiss({
        callBackVal: val
      });
    }
  }

  async dismissAlert() {
    if (this.alert) {
      await this.alert.dismiss({
        callBackVal: 4
      });
    }
  }

}
